import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints, MEDIA_URL } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import CustomFileUploads from "../common/CustomFileUploads";

const SUPPORTED_FORMATS = ["images/jpg", "images/jpeg", "images/png"];
const validationSchema = yup.object().shape({
  // images: yup
  //   .array()
  //   .min(1, "Logo is Required")
  //   .max(5, "You can't upload more than 5 image")
  //   .required("Logo is Required")
  //   .of(
  //     yup.mixed().test("fileSize", "File size is too large", (value) => {
  //       if (typeof value === "string") return true;
  //       return !value || value.size <= 1024 * 1024 * 3; // 5MB
  //     })
  //   ),
});

const DialogAddCategoryLogo = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      images: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
      // setDialogTitle(mode === "add" ? "Add Logo" : "Edit Logo");
      setDialogTitle("Add Logo");

      //   if (mode === "edit" && dataToEdit) {
      //     setSelectedFileNames({
      //       image: dataToEdit?.image || "",
      //       author_image: dataToEdit?.author_image || "",
      //     });
      //     setImageFile(null); // Set to null or initial value
      //     setAuthorImage(null); // Set to null or initial value
      //   } else {
      //     setSelectedFileNames({ image: "", author_image: "" });
      //     setImageFile(null);
      //     setAuthorImage(null);
      //   }

      reset({
        // author_name: dataToEdit?.author_name || "",
        // discription: dataToEdit?.discription || "",
        // category: dataToEdit?.category || "",
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    const payload = new FormData();
    payload.append("images", data.images);
    payload.append("client_catagory_id", dataToEdit.id);
    setLoading(true);
    let apiInstance = null;
    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ClientCategoryLogo.edit(dataToEdit.id),
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ClientCategoryLogo.create,
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        // onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}>
          <form id="blog-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <Controller
                    name="images"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <CustomFileUploads
                        multiple={true}
                        subtitle="(Max file size 3mb)"
                        files={value}
                        onChange={onChange}
                        title={"Add Logo"}
                        MediaUrl={MEDIA_URL}
                      />
                    )}
                  />
                  {errors?.images && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors?.images?.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="blog-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogAddCategoryLogo;
