import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import "react-datepicker/dist/react-datepicker.css";
import { CleaveNumberInput } from "src/@core/components/cleave-components";

const validationSchema = yup.object().shape({
  // mobile_number: yup
  //   .string()
  //   .trim()
  //   .matches(/^\+?[0-9]*$/, "Invalid Mobile Number")
  //   .required("Mobile number is required"),
  // linkedin: yup.string().trim().required("Please enter your Linkedin ID."),
  // facebook: yup.string().trim().required("Please enter your Facebook ID."),
  // instagram: yup.string().trim().required("Please enter your Instagram ID."),
});

const DialogAppBar = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      mobile_number: "",
      linkedin: "",
      facebook: "",
      instagram: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add " : "Edit ");

      reset({
        mobile_number: dataToEdit?.mobile_number || "",
        linkedin: dataToEdit?.linkedin || "",
        facebook: dataToEdit?.facebook || "",
        instagram: dataToEdit?.instagram || "",
      });
    }
  }, [dataToEdit, mode, open, reset]);
  const onSubmit = (data) => {
    let payload = {
      mobile_number: data.mobile_number,
      linkedin: data.linkedin,
      facebook: data.facebook,
      instagram: data.instagram,
    };
    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.AppBar.edit(dataToEdit.id),
        payload
      );
    } else {
      apiInstance = axiosInstance.post(ApiEndPoints.AppBar.create, payload);
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="plan-service-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="mobile_number"
                    error={Boolean(errors.mobile_number)}
                  >
                    Mobile Number
                  </FormLabel>
                  <Controller
                    name="mobile_number"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Mobile Number"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="mobile_number"
                        value={value}
                        error={Boolean(errors.mobile_number)}
                        InputProps={{
                          inputComponent: CleaveNumberInput,
                        }}
                      />
                    )}
                  />
                  {errors.mobile_number && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.mobile_number.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="linkedin"
                    error={Boolean(errors.linkedin)}
                  >
                    Linkedin
                  </FormLabel>
                  <Controller
                    name="linkedin"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Linkedin ID"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="linkedin"
                        value={value}
                        error={Boolean(errors.linkedin)}
                      />
                    )}
                  />
                  {errors.linkedin && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.linkedin.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="facebook"
                    error={Boolean(errors.facebook)}
                  >
                    Facebook
                  </FormLabel>
                  <Controller
                    name="facebook"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Facebook ID"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="facebook"
                        value={value}
                        error={Boolean(errors.facebook)}
                      />
                    )}
                  />
                  {errors.facebook && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.facebook.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="instagram"
                    error={Boolean(errors.instagram)}
                  >
                    Instagram
                  </FormLabel>
                  <Controller
                    name="instagram"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Instagram ID"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="instagram"
                        value={value}
                        error={Boolean(errors.instagram)}
                      />
                    )}
                  />
                  {errors.instagram && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.instagram.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="plan-service-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogAppBar;
