import { useEffect, useState, useRef, useCallback } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import DialogAddCategoryLogo from "src/views/dialog/DialogAddCategoryLogo";
import DialogAppBar from "src/views/dialog/DialogAppBar";
import TableAppBar from "src/views/tables/TableAppBar";

const AppBarPage = () => {
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [appBarData, setAppBarData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("active");

  // Testimonials
  const [appBarDialogOpen, setAppBarDialogOpen] = useState(false);
  const [appBarDailogMode, setAppBarDailogMode] = useState("add");
  const [appBarDataToEdit, setAppBarDataToEdit] = useState(null);
  const [diableAddButton, setDiableAddButton] = useState(false);

  const toggleAppBarFormDialog = (e, mode = "add", appBarDataToEdit = null) => {
    setAppBarDialogOpen((prev) => !prev);
    setAppBarDailogMode(mode);
    setAppBarDataToEdit(appBarDataToEdit);
  };

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [appBarDataToDelete, setAppBarDataToDelete] = useState(null);

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setAppBarDataToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.AppBar.list, { params })
      .then((response) => {
        setAppBarData(response.data.data);
        setTotalCount(response.data.totalItems);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setDiableAddButton(true);
        } else {
          setDiableAddButton(false); // Enable the button if there is no data
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.AppBar.delete(appBarDataToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, appBarDataToDelete, pageSize, search]
  );
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="App Bar Contents" />
            </Typography>
          }
          action={
            <Button
              variant="contained"
              disabled={diableAddButton}
              onClick={toggleAppBarFormDialog}
            >
              Add
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box sx={{ p: 5 }}>
              <TableAppBar
                search={search}
                loading={loading}
                rows={appBarData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleAppBarFormDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>

      <DialogAppBar
        mode={appBarDailogMode}
        open={appBarDialogOpen}
        toggle={toggleAppBarFormDialog}
        dataToEdit={appBarDataToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />

      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Client Category"
        subtitle="Are you sure you want to delete this Client Category?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default AppBarPage;
